it("names a direct commit's changed blobs when DELIVER omits the artifact list", async () => {
  const { repo, head, stateDir } = workspace("inferred-artifact");
  const installed = install(repo, stateDir);
  await start(installed, head, []);
  mkdirSync(join(repo, "deliverables"), { recursive: true });
  writeFileSync(join(repo, "deliverables", "review.md"), "# Maintenance review\n\nReady for the next session.\n");
  execFileSync("git", ["add", "-A"], { cwd: repo });
  execFileSync("git", ["-c", "user.email=t@t.t", "-c", "user.name=t", "commit", "-qm", "review"], { cwd: repo });
  const direct = execFileSync("git", ["rev-parse", "HEAD"], { cwd: repo, encoding: "utf8" }).trim();

  const pulse = (await call(installed, "palimpsest_continuity", { action: "pulse" })) as unknown as Pulse;
  expect(pulse.requiredAction).toMatchObject({ artifacts: ["deliverables/review.md"] });

  // A compliant session may trust the paths the pulse already observed instead of re-deriving them.
  const delivered = (await call(installed, "palimpsest_work", {
    action: "conclude",
    intent: "DELIVER",
    statement: "The committed review is the preserved result for this episode.",
  })) as unknown as Conclude;
  expect(delivered.state).toBe("RECORDED");
  expect(delivered.detail).toMatch(/No artifacts were supplied/iu);
  expect(delivered.conclusion?.check?.artifacts).toEqual([
    expect.objectContaining({
      path: "deliverables/review.md",
      present: true,
      tracked: true,
      committed: true,
      commit: direct,
    }),
  ]);

  // The pulse now reuses the recorded delivery instead of asking for a duplicate.
  const after = (await call(installed, "palimpsest_continuity", { action: "pulse" })) as unknown as Pulse;
  expect(after.requiredAction ?? null).toBeNull();
  expect(after.nextActions.mechanical[0]).toContain("reply using the recorded conclusion");
});

