import { execFileSync } from "node:child_process";
import { cpSync, mkdirSync, mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { pathToFileURL } from "node:url";

const repoRoot = "/run/stage/world";
const { installProduct } = await import(pathToFileURL(join(repoRoot, "dist/src/product.js")));
const root = mkdtempSync(join(tmpdir(), "sealed-handover-replay-"));
const repo = join(root, "world");
mkdirSync(repo);
const git = (...args) => execFileSync("git", ["-C", repo, ...args], { encoding: "utf8" }).trim();
git("init", "-q");
git("fetch", "-q", "/run/stage/world/evidence/basis.bundle", "HEAD:refs/heads/maintenance");
git("checkout", "-q", "maintenance");
const basis = git("rev-parse", "HEAD");
git("fetch", "-q", "/run/stage/world/evidence/case-2/candidate.bundle", "HEAD:refs/heads/replay");
const review = git("rev-parse", "replay");
const ancestor = execFileSync("git", ["-C", repo, "merge-base", "--is-ancestor", basis, review], { encoding: "utf8", stdio: "pipe" });
git("config", "user.name", "Sealed replay");
git("config", "user.email", "sealed-replay@example.invalid");

const stateDir = join(root, "state");
mkdirSync(stateDir);
for (const name of ["palimpsest.sqlite", "journal.sqlite"]) {
  cpSync(join(repoRoot, "evidence/case-3/owners", name), join(stateDir, name));
}
const deployment = installProduct({ tools: { register: () => () => undefined } }, {
  projectId: "grpc-migration-continuation",
  repository: repo,
  stateDir,
  execution: "in-place",
  toolProfile: "normal",
  standard: { statement: "Preserve the documented cold-handover review for the next session.", clauses: [], derivedFrom: [], confirmed: true, notes: [] },
});
let ordinal = 0;
const call = (name, args) => {
  const tool = deployment.tools.find(entry => entry.name === name);
  if (!tool) throw new Error(`missing ${name}`);
  const callId = `sealed-${++ordinal}`;
  return tool.execute(args, { name, callId, rootCallId: callId, arguments: args, signal: AbortSignal.timeout(20_000) });
};
const first = value => (value.nextActions?.mechanical ?? [])[0] ?? "";
try {
  const before = await call("palimpsest_continuity", { action: "pulse" });
  const beforeRequired = before.requiredAction ?? null;
  git("merge", "--quiet", "--ff-only", "replay");
  const afterMerge = await call("palimpsest_continuity", { action: "pulse" });
  const afterRequired = afterMerge.requiredAction ?? null;
  const delivered = await call("palimpsest_work", {
    action: "conclude",
    intent: "DELIVER",
    statement: "The merged cold-handover review is the preserved work result for this episode.",
  });
  const afterDelivery = await call("palimpsest_continuity", { action: "pulse" });
  const recorded = delivered?.conclusion?.check?.artifacts ?? [];
  const check = {
    basis,
    review,
    canonicalHead: before.basis.headCommit,
    beforeRequired,
    beforeFirst: first(before),
    afterRequired,
    afterFirst: first(afterMerge),
    deliveryState: delivered?.state ?? null,
    deliveryDetail: delivered?.detail ?? null,
    recorded: recorded.map(a => ({ path: a.path, present: a.present, tracked: a.tracked, committed: a.committed, commit: a.commit, digest: a.digest })),
    after: { requiredAction: afterDelivery.requiredAction ?? null, first: first(afterDelivery), episode: afterDelivery.episode?.state },
    status: deployment.controller.status(),
  };
  console.log("SEALED_REPLAY " + JSON.stringify(check));
  process.exitCode = delivered?.state === "RECORDED" &&
    recorded.some(a => a.path === "MAINTENANCE-REVIEW.md" && a.committed === true && a.commit === review) &&
    (afterDelivery.requiredAction ?? null) === null ? 0 : 1;
} finally {
  await deployment.dispose();
}
EOF
