async conclude(conclusionInput: EpisodeConclusionInput): Promise<EpisodeConclusionResult> {
  const current = await input.pulse.pulse();
  const readiness = current.episode.readiness;
  /**
   * PNWF-B/C: `pulse` already observes which blobs a direct commit changed. When a DELIVER
   * conclusion omits its artifacts, the product must not refuse the judgement merely because
   * the caller did not repeat that observation. The inferred paths are provenance candidates
   * from Git, not an acceptance of their content; an explicit list always wins, so a caller can
   * still narrow or override the delivered set.
   */
  const suppliedArtifacts = (conclusionInput.artifacts ?? []).map((path) => path.trim()).filter((path) => path !== "");
  const offeredArtifacts =
    current.requiredAction?.kind === "RECORD_DIRECT_DELIVERY" ? current.requiredAction.artifacts : [];
