const stateDir = join(root, "state");
mkdirSync(stateDir);
for (const name of ["palimpsest.sqlite", "journal.sqlite"]) {
  cpSync(join(repoRoot, "evidence/case-3/owners", name), join(stateDir, name));
}
const deployment = installProduct({ tools: { register: () => () => undefined } }, {
  projectId: "grpc-migration-continuation",
  repository: repo,
  stateDir,
  execution: "in-place",
  toolProfile: "normal",
  standard: { statement: "Preserve the documented cold-handover review for the next session.", clauses: [], derivedFrom: [], confirmed: true, notes: [] },
});
let ordinal = 0;
const call = (name, args) => {
  const tool = deployment.tools.find(entry => entry.name === name);
  if (!tool) throw new Error(`missing ${name}`);
  const callId = `sealed-${++ordinal}`;
  return tool.execute(args, { name, callId, rootCallId: callId, arguments: args, signal: AbortSignal.timeout(20_000) });
};
const first = value => (value.nextActions?.mechanical ?? [])[0] ?? "";
try {
