    beforeFirst: first(before),
    afterRequired,
    afterFirst: first(afterMerge),
    deliveryState: delivered?.state ?? null,
    deliveryDetail: delivered?.detail ?? null,
    recorded: recorded.map(a => ({ path: a.path, present: a.present, tracked: a.tracked, committed: a.committed, commit: a.commit, digest: a.digest })),
    after: { requiredAction: afterDelivery.requiredAction ?? null, first: first(afterDelivery), episode: afterDelivery.episode?.state },
    status: deployment.controller.status(),
  };
  console.log("SEALED_REPLAY " + JSON.stringify(check));
  process.exitCode = delivered?.state === "RECORDED" &&
